require_once __DIR__.'/bootstrap.php';requireAdmin();$id=sanitizeInt($_GET['id']??0);$s=getDB()->prepare('SELECT nama_file,nama_asli,mime_type FROM berkas_santri WHERE id=?');$s->execute([$id]);$f=$s->fetch();if(!$f){http_response_code(404);exit('Berkas tidak ditemukan.');}$path=UPLOADS_PATH.'/santri/'.basename($f['nama_file']);if(!is_file($path)){http_response_code(404);exit('File tidak ditemukan.');}while(ob_get_level())ob_end_clean();header('Content-Type: '.$f['mime_type']);header('Content-Length: '.filesize($path));header('Content-Disposition: inline; filename="'.preg_replace('/[^A-Za-z0-9._-]/','-',basename($f['nama_asli'])).'"');header('X-Content-Type-Options: nosniff');readfile($path);exit;
